-- ════════════════════════════════════════════════════════════
-- 演示数据（db/zz-demo-data.sql）
--
-- 用途：给看板 / 审核队列 / 报表提供**真实的库表数据**，替换前端 mock。
-- 规模：12 用户 / 60 商品 / 40 订单 + 商品图、审核记录、举报、申诉。
--
-- ⚠ 文件名为什么带 zz- 前缀（别改）：
--   db/ 整个目录挂进 MySQL 的 /docker-entrypoint-initdb.d/，首次启动按**文件名
--   顺序**自动执行其中的 .sql。ASCII 里数字 < 字母，所以任何数字前缀都会排在
--   schema.sql 之前——那时表还没建，开头的 DELETE 会直接把初始化打挂。取名
--   zz- 才能保证它排在 schema.sql 之后。副作用：首次启动会自动灌这份数据。
--
-- 用法（容器内执行，或本机 mysql 客户端）：
--   docker exec -i cm-mysql mysql -uroot -p'Campus@2026' --default-character-set=utf8mb4 campus_market < db/zz-demo-data.sql
--
-- 两条约定：
--   1. **确定性**：全部数值由固定种子的 LCG 生成，不依赖 RAND()，
--      任何人重跑得到同一份数据，论文截图才不会每次都变。
--   2. **幂等**：开头先清空七张业务表，可反复重灌；只灌演示库，别对生产用。
--
-- 「今天」固定为 2026-09-29（数据跨度 30 天），这样今日 KPI 不为 0。
-- ════════════════════════════════════════════════════════════

SET NAMES utf8mb4;

-- 清空（顺序：先明细后主表，避免孤儿行）
DELETE FROM trade_order;
DELETE FROM item_image;
DELETE FROM item_audit;
DELETE FROM appeal;
DELETE FROM report;
DELETE FROM item;
DELETE FROM app_user;

-- 学生用户（12 行）
-- 商品（60 行）
-- 商品图（120 行）
-- 商品审核（60 行）
-- 订单（40 行）
-- 举报（6 行）
-- 申诉（3 行）
